CREATE OR REPLACE FUNCTION public.add_cbt_question(p_exam_id uuid, p_question_text text, p_marks integer, p_question_number integer, p_options jsonb, p_difficulty text DEFAULT 'medium'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_question_id uuid;
  v_option jsonb;
  v_correct_count integer;
  v_option_count integer;
  v_exam_status text;
  v_exam_total integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_question_text IS NULL OR length(btrim(p_question_text)) = 0 THEN
    RAISE EXCEPTION 'Question text is required';
  END IF;
  IF p_marks IS NULL OR p_marks <= 0 THEN
    RAISE EXCEPTION 'Question marks must be positive';
  END IF;
  IF p_question_number IS NULL OR p_question_number <= 0 THEN
    RAISE EXCEPTION 'Question number must be positive';
  END IF;
  IF p_difficulty NOT IN ('easy','medium','hard') THEN
    RAISE EXCEPTION 'Invalid question difficulty';
  END IF;
  IF p_options IS NULL OR jsonb_typeof(p_options) <> 'array' THEN
    RAISE EXCEPTION 'Options must be a JSON array';
  END IF;

  -- Serialize edits against publishing and enforce tenant ownership.
  PERFORM public.assert_exam_access(p_exam_id);

  SELECT status, total_marks
    INTO v_exam_status, v_exam_total
  FROM public.cbt_exams
  WHERE id = p_exam_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Exam not found';
  END IF;
  IF v_exam_status <> 'draft' THEN
    RAISE EXCEPTION 'Questions can only be added to draft exams';
  END IF;

  SELECT count(*),
         count(*) FILTER (WHERE (item->>'is_correct')::boolean IS TRUE)
    INTO v_option_count, v_correct_count
  FROM jsonb_array_elements(p_options) AS item;

  IF v_option_count < 2 THEN
    RAISE EXCEPTION 'At least two answer options are required';
  END IF;
  IF v_correct_count <> 1 THEN
    RAISE EXCEPTION 'Exactly one correct option is required';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_options) AS item
    WHERE coalesce(btrim(item->>'text'), '') = ''
       OR coalesce(btrim(item->>'letter'), '') = ''
  ) THEN
    RAISE EXCEPTION 'Every option requires non-empty text and letter';
  END IF;

  INSERT INTO public.cbt_questions (
    exam_id, question_text, marks, question_number, question_type, difficulty
  ) VALUES (
    p_exam_id, btrim(p_question_text), p_marks, p_question_number, 'objective', p_difficulty
  ) RETURNING id INTO v_question_id;

  FOR v_option IN SELECT value FROM jsonb_array_elements(p_options)
  LOOP
    INSERT INTO public.cbt_options (
      question_id, option_text, is_correct, option_letter
    ) VALUES (
      v_question_id,
      btrim(v_option->>'text'),
      (v_option->>'is_correct')::boolean,
      upper(btrim(v_option->>'letter'))
    );
  END LOOP;

  UPDATE public.cbt_exams
  SET total_marks = total_marks + p_marks,
      updated_at = now()
  WHERE id = p_exam_id
  RETURNING total_marks INTO v_exam_total;

  RETURN jsonb_build_object(
    'success', true,
    'question_id', v_question_id,
    'question_number', p_question_number,
    'marks_added', p_marks,
    'total_marks', v_exam_total
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_exam_access(p_exam_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_exam_school uuid;
  v_provisioning_status text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'ACCESS_DENIED: AUTHENTICATION_REQUIRED';
  END IF;

  SELECT e.school_id, s.provisioning_status
    INTO v_exam_school, v_provisioning_status
  FROM public.cbt_exams e
  JOIN public.schools s ON s.id = e.school_id
  WHERE e.id = p_exam_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EXAM_NOT_FOUND';
  END IF;

  IF v_provisioning_status <> 'active' THEN
    RAISE EXCEPTION 'ACCESS_DENIED: SCHOOL_NOT_PROVISIONED';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.gradifi_school_memberships m
    WHERE m.user_id = auth.uid()
      AND m.school_id = v_exam_school
      AND m.status = 'active'
      AND m.member_role IN ('principal','school_admin','teacher','exam_officer')
  ) THEN
    RAISE EXCEPTION 'ACCESS_DENIED: ACTIVE_SCHOOL_ROLE_REQUIRED';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_pin_login(p_identifier text, p_pin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_actor public.identity_actors%rowtype;
begin
  if coalesce(length(p_pin),0) not in (4,6) or nullif(trim(p_identifier),'') is null then
    return jsonb_build_object('success',false,'error','INVALID_CREDENTIALS');
  end if;

  select * into v_actor
  from public.identity_actors
  where upper(login_identifier) = upper(trim(p_identifier))
    and status = 'active'
  limit 1;

  if not found or v_actor.locked_until > now() or v_actor.pin_hash is null
     or crypt(p_pin, v_actor.pin_hash) <> v_actor.pin_hash then
    if found then
      update public.identity_actors
      set failed_attempts = coalesce(failed_attempts,0) + 1,
          locked_until = case when coalesce(failed_attempts,0) + 1 >= 5 then now() + interval '15 minutes' else locked_until end,
          updated_at = now()
      where id = v_actor.id;
    end if;
    return jsonb_build_object('success',false,'error','INVALID_CREDENTIALS');
  end if;

  update public.identity_actors
  set failed_attempts = 0, locked_until = null, last_login_at = now(), updated_at = now()
  where id = v_actor.id;

  return jsonb_build_object(
    'success',true,'user_id',v_actor.auth_user_id,'actor_id',v_actor.id,
    'institution_id',v_actor.institution_id,'school_id',v_actor.school_id,
    'role',v_actor.actor_type,'login_id',v_actor.login_identifier
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.block_state_bypass()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.current_state IS DISTINCT FROM OLD.current_state THEN
    RAISE EXCEPTION 'Direct state mutation blocked. Use apply_fsm_event().';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.bootstrap_higher_institution(p_auth_user_id uuid, p_institution_name text, p_institution_type text, p_registration_number text, p_country text, p_address text, p_phone text, p_website text, p_dean_name text, p_dean_email text, p_dean_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_institution_id uuid;
  v_campus_id uuid;
  v_profile_id uuid;
  v_slug text;
  v_email text := lower(trim(p_dean_email));
begin
  if p_auth_user_id is null then raise exception 'AUTH_USER_REQUIRED'; end if;
  if nullif(trim(p_institution_name),'') is null
     or nullif(trim(p_institution_type),'') is null
     or nullif(trim(p_dean_name),'') is null
     or nullif(v_email,'') is null then
    raise exception 'INSTITUTION_AND_DEAN_REQUIRED';
  end if;
  if p_institution_type not in ('university','polytechnic','college_of_education') then
    raise exception 'UNSUPPORTED_HIGHER_INSTITUTION_TYPE';
  end if;
  if not exists (
    select 1 from auth.users u
    where u.id=p_auth_user_id and lower(u.email)=v_email
  ) then raise exception 'DEAN_AUTH_EMAIL_MISMATCH'; end if;
  if exists (select 1 from public.profiles p where p.user_id=p_auth_user_id)
     or exists (select 1 from public.identity_actors a where a.auth_user_id=p_auth_user_id) then
    raise exception 'ROOT_AUTH_IDENTITY_ALREADY_PROVISIONED';
  end if;
  if exists (select 1 from public.institutions i where i.registration_number=p_registration_number and p_registration_number is not null) then
    raise exception 'INSTITUTION_REGISTRATION_NUMBER_EXISTS';
  end if;

  insert into public.institutions(name,type,country,registration_number,address,phone,website_url,established_year,institution_category)
  values(trim(p_institution_name),p_institution_type,coalesce(nullif(trim(p_country),''),'Nigeria'),
    nullif(trim(p_registration_number),''),nullif(trim(p_address),''),nullif(trim(p_phone),''),
    nullif(trim(p_website),''),extract(year from now())::integer,p_institution_type)
  returning id into v_institution_id;

  v_slug := trim(both '-' from regexp_replace(lower(trim(p_institution_name)),'[^a-z0-9]+','-','g'));
  if v_slug='' then raise exception 'INSTITUTION_SLUG_INVALID'; end if;
  if exists(select 1 from public.schools s where s.url_slug=v_slug or s.slug=v_slug) then
    v_slug := v_slug || '-' || substr(replace(gen_random_uuid()::text,'-',''),1,6);
  end if;

  insert into public.schools(
    institution_id,school_name,email,phone,address,campus_address,campus_phone,
    school_type,url_slug,slug,provisioning_status
  ) values (
    v_institution_id,trim(p_institution_name)||' Main Campus',v_email,
    nullif(trim(p_phone),''),nullif(trim(p_address),''),nullif(trim(p_address),''),
    nullif(trim(p_phone),''),'tertiary',v_slug,v_slug,'unprovisioned'
  ) returning id into v_campus_id;

  insert into public.profiles(
    user_id,institution_id,school_id,full_name,role,email,phone,
    authentication_method,pin,pin_hash,pin_type,pin_requires_change,failed_attempts,locked_until
  ) values (
    p_auth_user_id,v_institution_id,v_campus_id,trim(p_dean_name),'dean',
    v_email,nullif(trim(p_dean_phone),''),'email',null,null,null,false,0,null
  ) returning id into v_profile_id;

  insert into public.identity_actors(
    auth_user_id,institution_id,school_id,actor_type,actor_record_id,
    login_identifier,auth_method,status,pin_hash,pin_changed_at,failed_attempts,authority_user_id
  ) values (
    p_auth_user_id,v_institution_id,v_campus_id,'dean',null,
    v_email,'email','active',null,now(),0,null
  );

  insert into public.institution_onboarding(
    institution_id,institution_created,school_created,classes_created,
    subjects_created,teachers_created,students_created,completed
  ) values(v_institution_id,true,true,false,false,false,false,false);

  insert into public.tenant_subscriptions(institution_id,plan_type,is_active)
  values(v_institution_id,'free',true);

  return jsonb_build_object(
    'success',true,'institution_id',v_institution_id,'school_id',v_campus_id,
    'profile_id',v_profile_id,'auth_user_id',p_auth_user_id,
    'actor_type','dean','url_slug',v_slug,
    'institution_path','/'||v_slug,'institution_name',trim(p_institution_name),
    'dean_email',v_email
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.bootstrap_institution_full(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_institution_id uuid;
    v_trace_id uuid := gen_random_uuid();
BEGIN

    -- 1. CREATE INSTITUTION
    INSERT INTO institutions (name, type, country, created_at)
    VALUES (
        payload->>'name',
        payload->>'type',
        payload->>'country',
        now()
    )
    RETURNING id INTO v_institution_id;

    INSERT INTO onboarding_audit (
        institution_id,
        trace_id,
        event_name,
        payload
    ) VALUES (
        v_institution_id,
        v_trace_id,
        'INSTITUTION_CREATED',
        payload
    );

    -- 2. CREATE DEFAULT ROLE PACKS
    INSERT INTO roles (institution_id, name, role_type)
    VALUES
        (v_institution_id, 'Principal', 'principal'),
        (v_institution_id, 'Teacher', 'teacher'),
        (v_institution_id, 'Student', 'student'),
        (v_institution_id, 'Bursar', 'bursar'),
        (v_institution_id, 'Parent', 'parent');

    INSERT INTO onboarding_audit (
        institution_id, trace_id, event_name, payload
    ) VALUES (
        v_institution_id, v_trace_id, 'ROLE_PACK_INITIALIZED', '{}'::jsonb
    );

    -- 3. GENERATE STRUCTURE (SCHOOL DEFAULT FIRST)
    IF payload->>'template' = 'secondary' THEN

        PERFORM initialize_secondary_classes(v_institution_id);

    ELSIF payload->>'template' = 'university' THEN

        INSERT INTO departments (institution_id, name, type)
        VALUES
            (v_institution_id, 'General Studies', 'academic'),
            (v_institution_id, 'Administration', 'admin');

    ELSE

        INSERT INTO departments (institution_id, name, type)
        VALUES
            (v_institution_id, 'Operations', 'admin');

    END IF;

    INSERT INTO onboarding_audit (
        institution_id, trace_id, event_name, payload
    ) VALUES (
        v_institution_id, v_trace_id, 'STRUCTURE_GENERATED', payload
    );

    -- 4. FINALIZE ONBOARDING
    UPDATE institution_onboarding
    SET completed = true,
        updated_at = now()
    WHERE institution_id = v_institution_id;

    INSERT INTO onboarding_audit (
        institution_id, trace_id, event_name, payload
    ) VALUES (
        v_institution_id, v_trace_id, 'ONBOARDING_COMPLETED', '{}'::jsonb
    );

    -- 5. RETURN SYSTEM READY STATE
    RETURN jsonb_build_object(
        'success', true,
        'institution_id', v_institution_id,
        'trace_id', v_trace_id,
        'status', 'ACTIVE'
    );

END;
$function$

CREATE OR REPLACE FUNCTION public.bootstrap_school_institution(p_auth_user_id uuid, p_institution_name text, p_institution_type text, p_registration_number text, p_country text, p_address text, p_state text, p_lga text, p_phone text, p_website text, p_principal_name text, p_principal_email text, p_principal_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_institution_id uuid;
  v_school_id uuid;
  v_profile_id uuid;
  v_slug text;
  v_email text := lower(trim(p_principal_email));
  v_category text;
begin
  if p_auth_user_id is null then raise exception 'AUTH_USER_REQUIRED'; end if;
  if nullif(trim(p_institution_name),'') is null
     or nullif(trim(p_institution_type),'') is null
     or nullif(trim(p_principal_name),'') is null
     or nullif(v_email,'') is null then
    raise exception 'INSTITUTION_AND_PRINCIPAL_REQUIRED';
  end if;
  if p_institution_type not in ('primary','secondary','k12','group_of_schools') then
    raise exception 'UNSUPPORTED_SCHOOL_INSTITUTION_TYPE';
  end if;
  if not exists (
    select 1 from auth.users u
    where u.id=p_auth_user_id and lower(u.email)=v_email
  ) then raise exception 'PRINCIPAL_AUTH_EMAIL_MISMATCH'; end if;
  if exists (select 1 from public.profiles p where p.user_id=p_auth_user_id)
     or exists (select 1 from public.identity_actors a where a.auth_user_id=p_auth_user_id) then
    raise exception 'ROOT_AUTH_IDENTITY_ALREADY_PROVISIONED';
  end if;
  if exists (select 1 from public.institutions i where i.registration_number=p_registration_number and p_registration_number is not null) then
    raise exception 'INSTITUTION_REGISTRATION_NUMBER_EXISTS';
  end if;

  v_category := case when p_institution_type='group_of_schools' then 'group_of_schools' else p_institution_type end;
  insert into public.institutions(name,type,country,registration_number,address,state,lga,phone,website_url,established_year,institution_category)
  values(trim(p_institution_name),p_institution_type,coalesce(nullif(trim(p_country),''),'Nigeria'),
    nullif(trim(p_registration_number),''),nullif(trim(p_address),''),nullif(trim(p_state),''),
    nullif(trim(p_lga),''),nullif(trim(p_phone),''),nullif(trim(p_website),''),extract(year from now())::integer,v_category)
  returning id into v_institution_id;

  v_slug := trim(both '-' from regexp_replace(lower(trim(p_institution_name)),'[^a-z0-9]+','-','g'));
  if v_slug='' then raise exception 'INSTITUTION_SLUG_INVALID'; end if;
  if exists(select 1 from public.schools s where s.url_slug=v_slug or s.slug=v_slug) then
    v_slug := v_slug || '-' || substr(replace(gen_random_uuid()::text,'-',''),1,6);
  end if;

  insert into public.schools(
    institution_id,school_name,principal_name,principal_email,email,phone,address,
    campus_address,campus_phone,school_type,url_slug,slug,provisioning_status
  ) values (
    v_institution_id,trim(p_institution_name),trim(p_principal_name),v_email,v_email,
    nullif(trim(p_phone),''),nullif(trim(p_address),''),nullif(trim(p_address),''),
    nullif(trim(p_phone),''),p_institution_type,v_slug,v_slug,'unprovisioned'
  ) returning id into v_school_id;

  insert into public.profiles(
    user_id,institution_id,school_id,full_name,role,email,phone,
    authentication_method,pin,pin_hash,pin_type,pin_requires_change,failed_attempts,locked_until
  ) values (
    p_auth_user_id,v_institution_id,v_school_id,trim(p_principal_name),'principal_admin',
    v_email,nullif(trim(p_principal_phone),''),'email',null,null,null,false,0,null
  ) returning id into v_profile_id;

  insert into public.identity_actors(
    auth_user_id,institution_id,school_id,actor_type,actor_record_id,
    login_identifier,auth_method,status,pin_hash,pin_changed_at,failed_attempts,authority_user_id
  ) values (
    p_auth_user_id,v_institution_id,v_school_id,'principal_admin',null,
    v_email,'email','active',null,now(),0,null
  );

  insert into public.gradifi_school_memberships(school_id,user_id,member_role,status,invited_by,activated_at)
  values(v_school_id,p_auth_user_id,'principal','active',p_auth_user_id,now());

  insert into public.institution_onboarding(
    institution_id,institution_created,school_created,classes_created,
    subjects_created,teachers_created,students_created,completed
  ) values(v_institution_id,true,true,false,false,false,false,false);

  insert into public.tenant_subscriptions(institution_id,plan_type,is_active)
  values(v_institution_id,'free',true);

  return jsonb_build_object(
    'success',true,'institution_id',v_institution_id,'school_id',v_school_id,
    'profile_id',v_profile_id,'auth_user_id',p_auth_user_id,
    'actor_type','principal_admin','url_slug',v_slug,
    'institution_path','/'||v_slug,'institution_name',trim(p_institution_name),
    'principal_email',v_email
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.calculate_grade(score numeric)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF score >= 75 THEN
        RETURN 'A1';
    ELSIF score >= 70 THEN
        RETURN 'B2';
    ELSIF score >= 65 THEN
        RETURN 'B3';
    ELSIF score >= 60 THEN
        RETURN 'C4';
    ELSIF score >= 55 THEN
        RETURN 'C5';
    ELSIF score >= 50 THEN
        RETURN 'C6';
    ELSIF score >= 45 THEN
        RETURN 'D7';
    ELSIF score >= 40 THEN
        RETURN 'E8';
    ELSE
        RETURN 'F9';
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.cbt_finalize_attempt(p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_attempt public.cbt_attempts%rowtype;
  v_result public.cbt_results_summary%rowtype;
  v_score integer;
  v_percentage numeric(5,2);
  v_grade char(1);
  v_status text;
  v_was_finalized boolean;
begin
  select * into v_attempt from public.cbt_attempts where id = p_attempt_id for update;
  if not found then raise exception 'CBT_ATTEMPT_NOT_FOUND'; end if;
  v_was_finalized := v_attempt.status in ('submitted','timeout');
  if v_attempt.status = 'in_progress' then
    v_status := case when now() >= v_attempt.deadline_at then 'timeout' else 'submitted' end;
    select coalesce(sum(a.marks_awarded),0) into v_score from public.cbt_answers a where a.attempt_id = p_attempt_id;
    if v_attempt.total_marks <= 0 then raise exception 'INVALID_ATTEMPT_TOTAL_MARKS'; end if;
    v_percentage := round((v_score::numeric / v_attempt.total_marks::numeric) * 100, 2);
    v_grade := case when v_percentage >= 75 then 'A' when v_percentage >= 65 then 'B'
      when v_percentage >= 50 then 'C' when v_percentage >= 40 then 'D' else 'F' end;
    update public.cbt_attempts
    set score = v_score, percentage = v_percentage, status = v_status,
        submitted_at = coalesce(submitted_at, now()), end_time = coalesce(end_time, now())
    where id = p_attempt_id returning * into v_attempt;
  elsif v_attempt.status not in ('submitted','timeout') then
    raise exception 'INVALID_ATTEMPT_STATE';
  else
    v_score := coalesce(v_attempt.score,0);
    v_percentage := coalesce(v_attempt.percentage,
      case when v_attempt.total_marks > 0 then round((v_score::numeric / v_attempt.total_marks::numeric) * 100, 2) else 0 end);
    v_grade := case when v_percentage >= 75 then 'A' when v_percentage >= 65 then 'B'
      when v_percentage >= 50 then 'C' when v_percentage >= 40 then 'D' else 'F' end;
  end if;
  insert into public.cbt_results_summary(
    exam_id, candidate_id, student_id, attempt_id, score, total_marks, percentage, grade
  ) values (
    v_attempt.exam_id, v_attempt.candidate_id, v_attempt.student_id, v_attempt.id,
    coalesce(v_attempt.score,0), v_attempt.total_marks, coalesce(v_attempt.percentage,0), v_grade
  ) on conflict (attempt_id) do nothing;
  select * into v_result from public.cbt_results_summary where attempt_id = p_attempt_id;
  return jsonb_build_object(
    'success', true, 'attempt_id', v_attempt.id, 'candidate_id', v_attempt.candidate_id,
    'attempt_number', v_attempt.attempt_number, 'status', v_attempt.status,
    'score', v_result.score, 'total_marks', v_result.total_marks, 'percentage', v_result.percentage,
    'grade', v_result.grade, 'result_id', v_result.id, 'already_finalized', v_was_finalized
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.cbt_get_or_create_candidate()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_student_id uuid;
  v_student_count integer;
  v_candidate_id uuid;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select count(*), (array_agg(s.id order by s.id))[1]
    into v_student_count, v_student_id
  from public.students s where s.user_id = v_uid;
  if v_student_count > 1 then
    raise exception 'CBT_IDENTITY_AMBIGUOUS: Auth user maps to multiple student rows';
  end if;
  if v_student_count = 1 then
    insert into public.cbt_candidates(candidate_type, student_id)
    values ('student', v_student_id)
    on conflict (student_id) where candidate_type = 'student'
    do update set student_id = excluded.student_id
    returning id into v_candidate_id;
  else
    insert into public.cbt_candidates(candidate_type, user_id)
    values ('individual', v_uid)
    on conflict (user_id) where candidate_type = 'individual'
    do update set user_id = excluded.user_id
    returning id into v_candidate_id;
  end if;
  return v_candidate_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.cbt_guard_session_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_attempt_status text; v_allowed boolean;
begin
  if new.id is distinct from old.id
    or new.attempt_id is distinct from old.attempt_id
    or new.exam_id is distinct from old.exam_id
    or new.student_id is distinct from old.student_id
    or new.candidate_id is distinct from old.candidate_id
    or new.created_at is distinct from old.created_at then
    raise exception 'CBT session identity fields are immutable';
  end if;
  if new.state <> old.state then
    v_allowed := case old.state
      when 'INITIALIZING' then new.state = 'AUTHENTICATED'
      when 'AUTHENTICATED' then new.state = 'LOADING_EXAM'
      when 'LOADING_EXAM' then new.state = 'INSTRUCTIONS_VIEW'
      when 'INSTRUCTIONS_VIEW' then new.state = 'ACTIVE_EXAM'
      when 'ACTIVE_EXAM' then new.state in ('PAUSED','SUBMITTED','SCORED')
      when 'PAUSED' then new.state in ('ACTIVE_EXAM','SCORED')
      when 'SUBMITTED' then new.state = 'SCORED'
      else false end;
    if not v_allowed then raise exception 'Invalid CBT session transition: % -> %', old.state, new.state; end if;
    if new.state in ('SUBMITTED','SCORED') then
      select status into v_attempt_status from public.cbt_attempts where id = old.attempt_id;
      if v_attempt_status = 'in_progress' then raise exception 'Cannot close CBT session while its attempt is still active'; end if;
    end if;
  end if;
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.cbt_prepare_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_exam public.cbt_exams%rowtype;
  v_candidate public.cbt_candidates%rowtype;
  v_next_number integer;
  v_deadline timestamptz;
begin
  select * into v_candidate from public.cbt_candidates where id = new.candidate_id for share;
  if not found then raise exception 'CBT_CANDIDATE_NOT_FOUND'; end if;
  if v_candidate.candidate_type = 'student' then
    if new.student_id is distinct from v_candidate.student_id then
      raise exception 'CBT_CANDIDATE_STUDENT_MISMATCH';
    end if;
  elsif new.student_id is not null then
    raise exception 'CBT_INDIVIDUAL_MUST_NOT_HAVE_STUDENT_ID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(new.exam_id::text || ':' || new.candidate_id::text, 0));
  select * into v_exam from public.cbt_exams where id = new.exam_id for share;
  if not found then raise exception 'CBT exam not found'; end if;
  if v_exam.status not in ('published','active') then raise exception 'CBT exam is not open for attempts'; end if;
  if v_exam.start_time is not null and now() < v_exam.start_time then raise exception 'CBT exam availability window has not opened'; end if;
  if v_exam.end_time is not null and now() >= v_exam.end_time then raise exception 'CBT exam availability window has closed'; end if;
  if new.attempt_number is null then
    select coalesce(max(attempt_number), 0) + 1 into v_next_number
    from public.cbt_attempts where exam_id = new.exam_id and candidate_id = new.candidate_id;
    new.attempt_number := v_next_number;
  end if;
  new.start_time := coalesce(new.start_time, now());
  v_deadline := new.start_time + make_interval(mins => v_exam.duration_minutes);
  if v_exam.end_time is not null then v_deadline := least(v_deadline, v_exam.end_time); end if;
  new.deadline_at := v_deadline;
  new.end_time := null;
  new.submitted_at := null;
  new.status := 'in_progress';
  new.total_marks := v_exam.total_marks;
  new.score := 0;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.cbt_reject_published_option_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_question_id uuid;
  v_status text;
BEGIN
  v_question_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.question_id ELSE NEW.question_id END;
  SELECT e.status INTO v_status
  FROM public.cbt_questions q JOIN public.cbt_exams e ON e.id=q.exam_id
  WHERE q.id=v_question_id;
  IF v_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'PUBLISHED_EXAM_CONTENT_IMMUTABLE';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.question_id IS DISTINCT FROM OLD.question_id THEN
    RAISE EXCEPTION 'OPTION_QUESTION_ID_IMMUTABLE';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.cbt_reject_published_question_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
