CREATE OR REPLACE FUNCTION public.create_cbt_attempt(p_exam_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_candidate_id uuid;
  v_student_id uuid;
  v_attempt public.cbt_attempts%rowtype;
  v_session public.cbt_sessions%rowtype;
  v_question_count integer;
  v_snapshot_count integer;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not public.cbt_student_can_access_exam(p_exam_id) then raise exception 'Candidate is not eligible to start this exam'; end if;
  v_candidate_id := public.cbt_get_or_create_candidate();
  select student_id into v_student_id from public.cbt_candidates
  where id = v_candidate_id and candidate_type = 'student';
  if v_student_id is null then raise exception 'INDIVIDUAL_EXAM_ACCESS_NOT_ENABLED_UNTIL_P0_2'; end if;
  select count(*) into v_question_count from public.cbt_questions where exam_id = p_exam_id;
  select count(*) into v_snapshot_count from public.gradifi_exam_question_snapshots where exam_id = p_exam_id;
  if v_question_count = 0 or v_snapshot_count <> v_question_count then raise exception 'Published exam snapshot is missing or incomplete'; end if;
  insert into public.cbt_attempts(exam_id, candidate_id, student_id)
  values (p_exam_id, v_candidate_id, v_student_id) returning * into v_attempt;
  insert into public.cbt_sessions(
    attempt_id, exam_id, candidate_id, student_id, state, current_question, remaining_time
  ) values (
    v_attempt.id, v_attempt.exam_id, v_candidate_id, v_student_id, 'INITIALIZING', 0,
    greatest(0, extract(epoch from (v_attempt.deadline_at-now()))::integer)
  ) returning * into v_session;
  return jsonb_build_object(
    'success', true, 'attempt_id', v_attempt.id, 'candidate_id', v_candidate_id,
    'attempt_number', v_attempt.attempt_number, 'session_id', v_session.id,
    'start_time', v_attempt.start_time, 'deadline_at', v_attempt.deadline_at,
    'status', v_attempt.status, 'snapshot_questions', v_snapshot_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_cbt_exam(p_school_id uuid, p_class_id uuid, p_subject_id uuid, p_term_id uuid, p_title text, p_description text, p_duration_minutes integer, p_pass_mark integer, p_exam_date timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_teacher_id uuid;
  v_exam_id uuid;
  v_class_school uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF p_title IS NULL OR length(btrim(p_title)) = 0 THEN
    RAISE EXCEPTION 'Exam title is required';
  END IF;
  IF p_duration_minutes IS NULL OR p_duration_minutes <= 0 THEN
    RAISE EXCEPTION 'Exam duration must be positive';
  END IF;
  IF p_pass_mark IS NULL OR p_pass_mark < 0 THEN
    RAISE EXCEPTION 'Pass mark cannot be negative';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.gradifi_school_memberships m
    JOIN public.schools s ON s.id = m.school_id
    WHERE m.user_id = auth.uid()
      AND m.school_id = p_school_id
      AND m.status = 'active'
      AND m.member_role IN ('principal','school_admin','teacher','exam_officer')
      AND s.provisioning_status = 'active'
  ) THEN
    RAISE EXCEPTION 'ACCESS_DENIED: ACTIVE_SCHOOL_ROLE_REQUIRED';
  END IF;

  SELECT c.school_id INTO v_class_school
  FROM public.classes c
  WHERE c.id = p_class_id;
  IF NOT FOUND OR v_class_school <> p_school_id THEN
    RAISE EXCEPTION 'Class does not belong to the requested school';
  END IF;

  SELECT t.id INTO v_teacher_id
  FROM public.teachers t
  WHERE t.user_id = auth.uid()
    AND t.school_id = p_school_id
  ORDER BY t.id
  LIMIT 1;

  IF v_teacher_id IS NULL THEN
    RAISE EXCEPTION 'Authorized staff identity is not linked to a teacher record required by the current exam schema';
  END IF;

  INSERT INTO public.cbt_exams (
    school_id,class_id,subject_id,term_id,title,description,duration_minutes,
    pass_mark,exam_date,created_by,status,current_state
  ) VALUES (
    p_school_id,p_class_id,p_subject_id,p_term_id,btrim(p_title),p_description,
    p_duration_minutes,p_pass_mark,p_exam_date,v_teacher_id,'draft','draft'
  ) RETURNING id INTO v_exam_id;

  RETURN jsonb_build_object('success',true,'exam_id',v_exam_id,'title',btrim(p_title),'status','draft');
END;
$function$

CREATE OR REPLACE FUNCTION public.create_school_with_classes(p_school_name text, p_school_type text, p_email text, p_phone text, p_address text, p_logo_url text, p_principal_name text, p_vice_principal_name text, p_institution_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
    new_school_id UUID;
    class_result JSONB;
BEGIN
    -- Insert school
    INSERT INTO schools (
        institution_id, school_name, email, phone, address, 
        logo_url, principal_name, vice_principal_name
    )
    VALUES (
        p_institution_id, p_school_name, p_email, p_phone, p_address,
        p_logo_url, p_principal_name, p_vice_principal_name
    )
    RETURNING id INTO new_school_id;

    -- Auto-initialize classes if it's a secondary school (case-insensitive)
    IF LOWER(p_school_type) = 'secondary' THEN
        class_result := initialize_secondary_classes(new_school_id);
    END IF;

    RETURN jsonb_build_object(
        'id', new_school_id,
        'school_name', p_school_name,
        'classes', class_result
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_supervisor_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  student_count INTEGER;
  max_capacity INTEGER;
BEGIN
  SELECT max_students INTO max_capacity
  FROM public.nuc_supervisors
  WHERE id = NEW.supervisor_id;

  SELECT COUNT(*) INTO student_count
  FROM public.nuc_supervisor_assignments
  WHERE supervisor_id = NEW.supervisor_id
    AND status = 'active';

  IF student_count >= max_capacity THEN
    RAISE EXCEPTION 'Supervisor capacity exceeded. Max % students allowed.', max_capacity;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fsm_block_direct_state_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN

    -- allow ONLY internal FSM kernel execution
    IF current_setting('fsm.internal_call', true) = 'true' THEN
        RETURN NEW;
    END IF;

    -- block all external mutations
    IF NEW.current_state IS DISTINCT FROM OLD.current_state THEN
        RAISE EXCEPTION
        'FSM VIOLATION: direct state mutation blocked. Use apply_fsm_event()';
    END IF;

    RETURN NEW;

END;
$function$

CREATE OR REPLACE FUNCTION public.generate_certificate_hash()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  hash_text TEXT;
BEGIN
  -- Combine certificate data into a single string
  hash_text := NEW.certificate_number || '|' || 
               NEW.institution_id::TEXT || '|' || 
               NEW.student_id::TEXT || '|' || 
               COALESCE(NEW.similarity_score::TEXT, '') || '|' || 
               EXTRACT(EPOCH FROM NEW.issued_at)::TEXT;
  
  -- Generate SHA-256 hash
  NEW.certificate_hash := ENCODE(
    SHA256(hash_text::BYTEA),
    'hex'
  );
  
  -- Generate verification URL
  NEW.verification_url := 'https://gradifi.vercel.app/verify/' || NEW.certificate_number;
  
  -- Generate QR code URL (using external API)
  NEW.qr_code_url := 'https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=' || NEW.verification_url;
  
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_certificate_number()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.certificate_number := 'GRD-' || TO_CHAR(NOW(), 'YYYY') || '-' || 
    LPAD((EXTRACT(EPOCH FROM NOW())::BIGINT % 1000000)::TEXT, 6, '0');
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_student_number(p_school_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_next_number INT;
    v_prefix TEXT;
    v_school_name TEXT;
    v_result TEXT;
BEGIN
    -- Get school name for prefix
    SELECT school_name INTO v_school_name
    FROM schools
    WHERE id = p_school_id;
    
    -- Create prefix from school name (first 3 letters uppercase)
    v_prefix := UPPER(LEFT(REGEXP_REPLACE(v_school_name, '[^a-zA-Z]', '', 'g'), 3));
    
    -- Fallback if no prefix
    IF v_prefix IS NULL OR v_prefix = '' THEN
        v_prefix := 'SCH';
    END IF;
    
    -- Get or create sequence
    INSERT INTO student_number_sequences (school_id, last_number, prefix)
    VALUES (p_school_id, 0, v_prefix)
    ON CONFLICT (school_id) DO UPDATE
    SET last_number = student_number_sequences.last_number + 1,
        updated_at = NOW()
    RETURNING last_number INTO v_next_number;
    
    -- Format: PREFIX-YEAR-5DIGIT (e.g., STM-2026-00001)
    v_result := v_prefix || '-' || 
                TO_CHAR(CURRENT_DATE, 'YYYY') || '-' || 
                LPAD(v_next_number::TEXT, 5, '0');
    
    RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_cbt_exam_questions(p_exam_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth', 'extensions'
AS $function$
DECLARE
  v_result jsonb;
  v_bad_hashes integer;
BEGIN
  IF auth.uid() IS NULL OR NOT public.cbt_student_can_access_exam(p_exam_id) THEN
    RAISE EXCEPTION 'Student is not eligible to view this exam';
  END IF;
  SELECT count(*) FILTER (WHERE s.content_sha256 <> encode(extensions.digest(
      (s.question_payload::text || s.answer_key_payload::text)::bytea,'sha256'),'hex'))
  INTO v_bad_hashes
  FROM public.gradifi_exam_question_snapshots s WHERE s.exam_id=p_exam_id;
  IF v_bad_hashes IS NULL OR v_bad_hashes>0 THEN
    RAISE EXCEPTION 'EXAM_SNAPSHOT_INTEGRITY_FAILURE';
  END IF;

  SELECT jsonb_build_object(
    'success',true,'exam_id',p_exam_id,'status','published',
    'total_questions',count(*),
    'total_marks',coalesce(sum((s.question_payload->>'marks')::integer),0),
    'questions',coalesce(jsonb_agg(s.question_payload ORDER BY s.display_order),'[]'::jsonb)
  ) INTO v_result
  FROM public.gradifi_exam_question_snapshots s WHERE s.exam_id=p_exam_id;
  IF coalesce((v_result->>'total_questions')::integer,0)=0 THEN
    RAISE EXCEPTION 'PUBLISHED_EXAM_SNAPSHOT_MISSING';
  END IF;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_course_adviser_stats(p_adviser_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_total_advisees bigint;
  v_at_risk_students bigint;
  v_avg_cgpa numeric;
begin
  if auth.uid() is null or not exists (
    select 1 from public.identity_actors ia
    where ia.auth_user_id = auth.uid()
      and ia.actor_type = 'adviser'
      and ia.actor_record_id = p_adviser_id
      and ia.status = 'active'
  ) then raise exception 'ADVISER_SCOPE_DENIED'; end if;

  select count(*) into v_total_advisees
  from public.students where adviser_id = p_adviser_id;
  select count(*) into v_at_risk_students
  from public.students where adviser_id = p_adviser_id and cgpa < 2.0;
  select coalesce(avg(cgpa), 0) into v_avg_cgpa
  from public.students where adviser_id = p_adviser_id;

  return jsonb_build_object(
    'total_advisees', v_total_advisees,
    'at_risk_students', v_at_risk_students,
    'avg_cgpa', round(v_avg_cgpa, 2)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_dean_dashboard_stats(p_institution_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_total_students bigint;
  v_total_departments bigint;
  v_pending_approvals bigint;
begin
  if auth.uid() is null or not exists (
    select 1 from public.profiles p
    where p.user_id = auth.uid()
      and p.role = 'dean'
      and p.institution_id = p_institution_id
  ) then raise exception 'DEAN_INSTITUTION_SCOPE_DENIED'; end if;

  select count(*) into v_total_students
  from public.students where institution_id = p_institution_id;
  select count(*) into v_total_departments
  from public.nuc_departments where institution_id = p_institution_id;
  select count(*) into v_pending_approvals
  from public.plagiarism_checks
  where institution_id = p_institution_id and status = 'pending_dean';

  return jsonb_build_object(
    'total_students', v_total_students,
    'total_departments', v_total_departments,
    'pending_approvals', v_pending_approvals
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_hod_dashboard_stats(p_institution_id uuid, p_department_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_total_students bigint;
  v_total_projects bigint;
  v_pending_reviews bigint;
begin
  if auth.uid() is null or not exists (
    select 1
    from public.identity_actors ia
    join public.nuc_departments nd on nd.hod_id = ia.actor_record_id
    where ia.auth_user_id = auth.uid()
      and ia.actor_type = 'hod'
      and ia.institution_id = p_institution_id
      and nd.id = p_department_id
      and nd.institution_id = p_institution_id
  ) then raise exception 'HOD_DEPARTMENT_SCOPE_DENIED'; end if;

  select count(*) into v_total_students
  from public.students
  where institution_id = p_institution_id and department_id = p_department_id;
  select count(*) into v_total_projects
  from public.projects
  where institution_id = p_institution_id and department_id = p_department_id;
  select count(*) into v_pending_reviews
  from public.plagiarism_checks pc
  join public.students s on s.id = pc.student_id
  where s.institution_id = p_institution_id
    and s.department_id = p_department_id
    and pc.status = 'pending_hod';

  return jsonb_build_object(
    'total_students', v_total_students,
    'total_projects', v_total_projects,
    'pending_reviews', v_pending_reviews
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_human_ai_agreement(p_teacher_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_result JSONB;
    v_total INTEGER;
    v_agreed INTEGER;
    v_agreement_rate NUMERIC;
BEGIN
    -- Count reviewed scripts where ai_score and final_score match
    SELECT 
        COUNT(*) FILTER (WHERE status IN ('approved', 'overridden', 'released')),
        COUNT(*) FILTER (WHERE status IN ('approved', 'overridden', 'released') AND ABS(COALESCE(ai_score, 0) - COALESCE(final_score, 0)) < 0.5)
    INTO v_total, v_agreed
    FROM public.answer_scripts
    WHERE (p_teacher_id IS NULL OR teacher_id = p_teacher_id);

    IF v_total IS NULL OR v_total = 0 THEN
        RETURN jsonb_build_object(
            'total_reviewed', 0,
            'agreement_count', 0,
            'agreement_rate', 0,
            'status', 'no_data'
        );
    END IF;

    v_agreement_rate := ROUND((v_agreed::NUMERIC / v_total::NUMERIC) * 100);

    RETURN jsonb_build_object(
        'total_reviewed', v_total,
        'agreement_count', v_agreed,
        'agreement_rate', v_agreement_rate,
        'status', CASE 
            WHEN v_agreement_rate >= 90 THEN 'excellent'
            WHEN v_agreement_rate >= 70 THEN 'good'
            WHEN v_agreement_rate >= 50 THEN 'fair'
            ELSE 'needs_review'
        END
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_parent_children(p_parent_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(student_id uuid, student_name text, class_name text, student_number text, relationship text, is_primary boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_profile_id uuid;
  v_parent_id uuid;
begin
  select p.id into v_profile_id
  from public.profiles p
  where p.user_id = auth.uid() and p.role = 'parent';
  if v_profile_id is null then raise exception 'PARENT_AUTH_REQUIRED'; end if;

  select p.id into v_parent_id
  from public.parents p
  where p.profile_id = v_profile_id;
  if v_parent_id is null then raise exception 'PARENT_RECORD_NOT_FOUND'; end if;

  if p_parent_id is not null and p_parent_id not in (v_parent_id, v_profile_id) then
    raise exception 'PARENT_SCOPE_DENIED';
  end if;

  return query
  select s.id, s.first_name || ' ' || s.last_name, c.name,
         s.student_number, spr.relationship_type, spr.is_primary
  from public.student_parent_relationships spr
  join public.students s on s.id = spr.student_id
  join public.classes c on c.id = s.class_id
  where spr.parent_id = v_parent_id
  order by s.first_name;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_parent_dashboard_stats(p_parent_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_profile_id uuid;
  v_parent_id uuid;
  v_parent_name text;
  v_wards jsonb;
begin
  select p.id, p.full_name into v_profile_id, v_parent_name
  from public.profiles p
  where p.user_id = auth.uid() and p.role = 'parent';
  if v_profile_id is null then raise exception 'PARENT_AUTH_REQUIRED'; end if;

  select p.id into v_parent_id
  from public.parents p
  where p.profile_id = v_profile_id;
  if v_parent_id is null then raise exception 'PARENT_RECORD_NOT_FOUND'; end if;

  if p_parent_id is not null and p_parent_id not in (v_parent_id, v_profile_id) then
    raise exception 'PARENT_SCOPE_DENIED';
  end if;

  select jsonb_agg(
    jsonb_build_object(
      'student_id', s.id,
      'student_name', s.first_name || ' ' || s.last_name,
      'student_number', s.student_number,
      'class_name', c.name,
      'class_rank', coalesce((
        select cr.position from public.cbt_results_summary cr
        where cr.student_id = s.id order by cr.created_at desc limit 1
      ), 0),
      'total_students_in_class', (
        select count(*) from public.students classmates where classmates.class_id = s.class_id
      ),
      'attendance_rate', null,
      'term_avg_score', coalesce((
        select avg(cr.percentage) from public.cbt_results_summary cr where cr.student_id = s.id
      ), 0)
    )
  ) into v_wards
  from public.student_parent_relationships spr
  join public.students s on s.id = spr.student_id
  join public.classes c on c.id = s.class_id
  where spr.parent_id = v_parent_id;

  return jsonb_build_object(
    'parent_name', v_parent_name,
    'wards', coalesce(v_wards, '[]'::jsonb),
    'total_wards', coalesce(jsonb_array_length(v_wards), 0)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_principal_dashboard_stats(p_school_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_result jsonb;
  v_school_name text;
  v_total_students bigint;
  v_total_teachers bigint;
  v_total_classes bigint;
begin
  if auth.uid() is null or not exists (
    select 1 from public.profiles p
