CREATE OR REPLACE FUNCTION public.gradifi_assert_school_principal_invariant(p_school_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_status text;
  v_principal_count integer;
BEGIN
  SELECT s.provisioning_status
    INTO v_status
  FROM public.schools s
  WHERE s.id = p_school_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_status = 'active' THEN
    SELECT count(*)::integer
      INTO v_principal_count
    FROM public.gradifi_school_memberships m
    WHERE m.school_id = p_school_id
      AND m.member_role = 'principal'
      AND m.status = 'active';

    IF v_principal_count <> 1 THEN
      RAISE EXCEPTION
        'Active school % must have exactly one active principal; found %',
        p_school_id, v_principal_count
        USING ERRCODE = '23514';
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.gradifi_check_school_principal_invariant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'schools' THEN
    IF TG_OP <> 'DELETE' THEN
      PERFORM public.gradifi_assert_school_principal_invariant(NEW.id);
    END IF;
  ELSE
    IF TG_OP <> 'INSERT' THEN
      PERFORM public.gradifi_assert_school_principal_invariant(OLD.school_id);
    END IF;
    IF TG_OP <> 'DELETE' THEN
      IF TG_OP = 'INSERT' OR NEW.school_id IS DISTINCT FROM OLD.school_id THEN
        PERFORM public.gradifi_assert_school_principal_invariant(NEW.school_id);
      END IF;
      IF TG_OP = 'UPDATE' AND NEW.school_id = OLD.school_id THEN
        PERFORM public.gradifi_assert_school_principal_invariant(NEW.school_id);
      END IF;
    END IF;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.gradifi_guard_profile_authority_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if auth.uid() is not null and (
    new.user_id is distinct from old.user_id
    or new.role is distinct from old.role
    or new.school_id is distinct from old.school_id
    or new.institution_id is distinct from old.institution_id
  ) then
    raise exception 'Profile authority fields can only be changed by trusted onboarding administration';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gradifi_guard_school_provisioning_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.provisioning_status <> 'unprovisioned' AND current_user <> 'postgres' THEN
      RAISE EXCEPTION 'School activation must use a trusted onboarding operation'
        USING ERRCODE = '42501';
    END IF;
  ELSIF NEW.provisioning_status IS DISTINCT FROM OLD.provisioning_status
        AND current_user <> 'postgres' THEN
    RAISE EXCEPTION 'School provisioning status is managed by trusted onboarding operations'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.gradifi_reject_audit_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF current_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'audit_logs is append-only; % is prohibited', TG_OP
    USING ERRCODE = '42501';
END;
$function$

CREATE OR REPLACE FUNCTION public.invite_school_member(p_school_id uuid, p_user_id uuid, p_member_role text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_profile uuid;
  v_actor_role text;
  v_membership_id uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF p_user_id = v_actor THEN
    RAISE EXCEPTION 'Self-invitation is prohibited' USING ERRCODE = '42501';
  END IF;
  IF p_member_role NOT IN ('school_admin', 'teacher', 'exam_officer') THEN
    RAISE EXCEPTION 'Unsupported invitation role' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.schools WHERE id = p_school_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'School not found'; END IF;

  SELECT m.member_role INTO v_actor_role
  FROM public.gradifi_school_memberships m
  WHERE m.school_id = p_school_id
    AND m.user_id = v_actor
    AND m.status = 'active'
    AND m.member_role IN ('principal', 'school_admin')
  FOR UPDATE;

  IF v_actor_role IS NULL THEN
    RAISE EXCEPTION 'Active school principal or school administrator required'
      USING ERRCODE = '42501';
  END IF;
  IF p_member_role = 'school_admin' AND v_actor_role <> 'principal' THEN
    RAISE EXCEPTION 'Only the principal may appoint a school administrator'
      USING ERRCODE = '42501';
  END IF;

  SELECT p.id INTO v_actor_profile
  FROM public.profiles p
  WHERE p.user_id = v_actor;
  IF v_actor_profile IS NULL THEN
    RAISE EXCEPTION 'Actor profile is required for audit attribution';
  END IF;

  INSERT INTO public.gradifi_school_memberships
    (school_id, user_id, member_role, status, invited_by)
  VALUES
    (p_school_id, p_user_id, p_member_role, 'invited', v_actor)
  RETURNING id INTO v_membership_id;

  INSERT INTO public.audit_logs
    (actor_id, action, entity, entity_id, "before", "after", metadata)
  VALUES
    (v_actor_profile, 'school_membership.invited',
     'gradifi_school_memberships', v_membership_id::text,
     NULL,
     jsonb_build_object('school_id', p_school_id, 'user_id', p_user_id,
                        'member_role', p_member_role, 'status', 'invited'),
     jsonb_build_object('actor_auth_user_id', v_actor));

  RETURN v_membership_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.persist_cbt_session_snapshot(p_session_id uuid, p_current_question integer, p_remaining_time integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_session public.cbt_sessions%rowtype;
  v_attempt public.cbt_attempts%rowtype;
  v_question_count integer;
  v_remaining integer;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if p_session_id is null then raise exception 'Session identifier is required'; end if;
  if p_current_question is null or p_current_question < 0 then raise exception 'Current question index must be zero or greater'; end if;
  if p_remaining_time is null or p_remaining_time < 0 then raise exception 'Remaining time must be zero or greater'; end if;
  select * into v_session from public.cbt_sessions where id = p_session_id for update;
  if not found then raise exception 'CBT_SESSION_NOT_FOUND'; end if;
  if not public.cbt_candidate_is_owner(v_session.candidate_id) then raise exception 'CBT_SESSION_NOT_OWNED'; end if;
  if v_session.state not in ('ACTIVE_EXAM','PAUSED') then raise exception 'CBT_SESSION_NOT_PERSISTABLE_IN_CURRENT_STATE'; end if;
  select * into v_attempt from public.cbt_attempts
  where id = v_session.attempt_id and exam_id = v_session.exam_id and candidate_id = v_session.candidate_id for update;
  if not found or v_attempt.status <> 'in_progress' then raise exception 'CBT_ATTEMPT_NOT_ACTIVE'; end if;
  if now() >= v_attempt.deadline_at then raise exception 'CBT_ATTEMPT_DEADLINE_EXPIRED'; end if;
  select count(*) into v_question_count from public.gradifi_exam_question_snapshots where exam_id = v_session.exam_id;
  if v_question_count <= 0 or p_current_question >= v_question_count then raise exception 'CBT_CURRENT_QUESTION_OUT_OF_RANGE'; end if;
  v_remaining := least(p_remaining_time,greatest(0,ceil(extract(epoch from (v_attempt.deadline_at-now())))::integer));
  update public.cbt_sessions set current_question = p_current_question, remaining_time = v_remaining, updated_at = now()
  where id = v_session.id returning * into v_session;
  insert into public.cbt_session_snapshots(session_id,state,current_question,remaining_time)
  values (v_session.id,v_session.state,v_session.current_question,v_session.remaining_time);
  return jsonb_build_object('success',true,'session_id',v_session.id,'candidate_id',v_session.candidate_id,
    'state',v_session.state,'current_question',v_session.current_question,'remaining_time',v_session.remaining_time);
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_cbt_exam(p_exam_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth', 'extensions'
AS $function$
DECLARE
  v_exam public.cbt_exams%rowtype;
  v_question_count integer;
  v_question_marks integer;
  v_snapshot_count integer;
BEGIN
  PERFORM public.assert_exam_access(p_exam_id);
  SELECT * INTO v_exam FROM public.cbt_exams WHERE id=p_exam_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'EXAM_NOT_FOUND'; END IF;
  IF v_exam.status <> 'draft' OR v_exam.current_state <> 'draft' THEN
    RAISE EXCEPTION 'Only a draft exam can be published';
  END IF;

  SELECT count(*), coalesce(sum(q.marks),0)
  INTO v_question_count,v_question_marks
  FROM public.cbt_questions q WHERE q.exam_id=p_exam_id;

  IF v_question_count=0 OR v_question_marks<=0 THEN
    RAISE EXCEPTION 'Cannot publish an exam without positively marked questions';
  END IF;
  IF v_exam.total_marks<>v_question_marks THEN
    RAISE EXCEPTION 'Exam total marks do not match question marks';
  END IF;
  IF v_exam.pass_mark>v_question_marks THEN
    RAISE EXCEPTION 'Pass mark cannot exceed total marks';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.cbt_questions q
    WHERE q.exam_id=p_exam_id AND (
      q.question_type IS DISTINCT FROM 'objective'
      OR q.marks<=0
      OR (SELECT count(*) FROM public.cbt_options o WHERE o.question_id=q.id)<2
      OR (SELECT count(*) FROM public.cbt_options o WHERE o.question_id=q.id AND o.is_correct IS TRUE)<>1
    )
  ) THEN
    RAISE EXCEPTION 'Every published CBT question must be objective with at least two options and exactly one correct answer';
  END IF;

  SELECT count(*) INTO v_snapshot_count
  FROM public.gradifi_exam_question_snapshots s WHERE s.exam_id=p_exam_id;
  IF v_snapshot_count<>0 THEN
    RAISE EXCEPTION 'Snapshot rows already exist for this draft exam; investigate before publishing';
  END IF;

  INSERT INTO public.gradifi_exam_question_snapshots
    (exam_id, source_question_version_id, display_order, question_payload, answer_key_payload, content_sha256)
  SELECT
    p_exam_id,
    NULL,
    q.question_number,
    jsonb_build_object(
      'question_id',q.id,'text',q.question_text,'marks',q.marks,
      'number',q.question_number,'type',q.question_type,'image_url',q.image_url,
      'options',(SELECT jsonb_agg(jsonb_build_object('id',o.id,'text',o.option_text,'letter',o.option_letter)
                                 ORDER BY o.option_letter)
                 FROM public.cbt_options o WHERE o.question_id=q.id)
    ),
    jsonb_build_object(
      'question_id',q.id,'marks',q.marks,
      'correct_option_id',(SELECT o.id FROM public.cbt_options o
                           WHERE o.question_id=q.id AND o.is_correct IS TRUE)
    ),
    encode(extensions.digest(
      (jsonb_build_object(
        'question_id',q.id,'text',q.question_text,'marks',q.marks,
        'number',q.question_number,'type',q.question_type,'image_url',q.image_url,
        'options',(SELECT jsonb_agg(jsonb_build_object('id',o.id,'text',o.option_text,'letter',o.option_letter)
                                   ORDER BY o.option_letter)
                   FROM public.cbt_options o WHERE o.question_id=q.id)
      )::text || jsonb_build_object(
        'question_id',q.id,'marks',q.marks,
        'correct_option_id',(SELECT o.id FROM public.cbt_options o
                             WHERE o.question_id=q.id AND o.is_correct IS TRUE)
      )::text)::bytea,'sha256'),'hex')
  FROM public.cbt_questions q
  WHERE q.exam_id=p_exam_id
  ORDER BY q.question_number;

  UPDATE public.cbt_exams
  SET status='published', current_state='active',
      start_time=coalesce(start_time,now()),
      end_time=coalesce(end_time,coalesce(start_time,now()) + make_interval(mins=>duration_minutes)),
      updated_at=now()
  WHERE id=p_exam_id RETURNING * INTO v_exam;

  RETURN jsonb_build_object('success',true,'exam_id',p_exam_id,'status',v_exam.status,
    'start_time',v_exam.start_time,'end_time',v_exam.end_time,
    'duration_minutes',v_exam.duration_minutes,'total_questions',v_question_count,
    'total_marks',v_question_marks,'snapshot_count',v_question_count);
END;
$function$

