$function$

CREATE OR REPLACE FUNCTION public.recover_stuck_attempts()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_id uuid;
  v_count integer := 0;
BEGIN
  FOR v_id IN
    SELECT id FROM public.cbt_attempts
    WHERE status='in_progress' AND deadline_at<=now()
    ORDER BY deadline_at
    FOR UPDATE SKIP LOCKED
  LOOP
    PERFORM public.cbt_finalize_attempt(v_id);
    v_count := v_count+1;
  END LOOP;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_teacher_identity()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID;
    teacher_record RECORD;
BEGIN
    v_user_id := auth.uid();
    
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('error', 'Not authenticated', 'found', false);
    END IF;
    
    -- Try to find teacher by user_id
    SELECT t.id as teacher_id, t.school_id, t.name as teacher_name, t.email as teacher_email
    INTO teacher_record
    FROM teachers t
    WHERE t.user_id = v_user_id;
    
    IF NOT FOUND THEN
        -- Try by email match
        SELECT t.id as teacher_id, t.school_id, t.name as teacher_name, t.email as teacher_email
        INTO teacher_record
        FROM teachers t
        WHERE t.email = (SELECT email FROM auth.users WHERE id = v_user_id);
        
        IF FOUND THEN
            UPDATE teachers SET user_id = v_user_id WHERE id = teacher_record.teacher_id;
        END IF;
    END IF;
    
    IF teacher_record.teacher_id IS NULL THEN
        RETURN jsonb_build_object('found', false, 'message', 'No teacher found for this user');
    END IF;
    
    RETURN row_to_json(teacher_record)::jsonb;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_tenant_context(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_institution_id uuid;
  v_school_id uuid;
  v_role text;
BEGIN

  -- find actor
  SELECT institution_id, school_id, role
  INTO v_institution_id, v_school_id, v_role
  FROM profiles
  WHERE user_id = p_user_id;

  -- fallback resolution if missing institution
  IF v_institution_id IS NULL THEN
    SELECT institution_id INTO v_institution_id
    FROM schools
    WHERE id = v_school_id;
  END IF;

  RETURN jsonb_build_object(
    'institution_id', v_institution_id,
    'school_id', v_school_id,
    'role', v_role
  );

END;
$function$

CREATE OR REPLACE FUNCTION public.set_pin(p_new_pin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_role text;
begin
  if v_user_id is null then raise exception 'AUTH_REQUIRED'; end if;
  select role into v_role from public.profiles where user_id = v_user_id;
  if v_role is null then raise exception 'PROFILE_NOT_FOUND'; end if;
  if v_role not in ('vice_principal','bursar','teacher','student','parent','hod','adviser','lecturer') then
    raise exception 'PIN_AUTHENTICATION_NOT_ALLOWED_FOR_ROLE';
  end if;
  if length(p_new_pin) not in (4,6) or p_new_pin !~ '^[0-9]{4,6}$'
     or length(p_new_pin) <> (case when v_role in ('student','parent') then 4 else 6 end) then
    raise exception 'INVALID_PIN_LENGTH';
  end if;
  update public.profiles
  set pin = null, pin_hash = crypt(p_new_pin, gen_salt('bf')),
      pin_changed_at = now(), pin_requires_change = false,
      failed_attempts = 0, locked_until = null
  where user_id = v_user_id;
  update public.identity_actors
  set pin_hash = crypt(p_new_pin, gen_salt('bf')), pin_changed_at = now(),
      failed_attempts = 0, locked_until = null, updated_at = now()
  where auth_user_id = v_user_id;
  return jsonb_build_object('success', true, 'pin_requires_change', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_school_member_status(p_membership_id uuid, p_new_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_profile uuid;
  v_actor_role text;
  v_school_id uuid;
  v_target_user uuid;
  v_target_role text;
  v_old_status text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  IF p_new_status NOT IN ('active', 'suspended', 'revoked') THEN
    RAISE EXCEPTION 'Unsupported membership status' USING ERRCODE='22023';
  END IF;

  SELECT school_id INTO v_school_id
  FROM public.gradifi_school_memberships
  WHERE id = p_membership_id;
  IF v_school_id IS NULL THEN RAISE EXCEPTION 'Membership not found'; END IF;

  -- Match the lock order used by invitation and principal succession.
  PERFORM 1 FROM public.schools WHERE id = v_school_id FOR UPDATE;

  SELECT user_id, member_role, status
    INTO v_target_user, v_target_role, v_old_status
  FROM public.gradifi_school_memberships
  WHERE id = p_membership_id AND school_id = v_school_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Membership not found'; END IF;

  IF v_target_user = v_actor THEN RAISE EXCEPTION 'Self-status modification is prohibited' USING ERRCODE='42501'; END IF;
  IF v_target_role = 'principal' THEN
    RAISE EXCEPTION 'Principal status can change only through atomic succession'
      USING ERRCODE = '42501';
  END IF;
  IF v_old_status = 'revoked' THEN RAISE EXCEPTION 'Revoked membership is terminal'; END IF;
  IF v_old_status = p_new_status THEN RETURN; END IF;

  SELECT member_role INTO v_actor_role
  FROM public.gradifi_school_memberships
  WHERE school_id = v_school_id AND user_id = v_actor
    AND status = 'active' AND member_role IN ('principal','school_admin')
  FOR UPDATE;

  IF v_actor_role IS NULL THEN RAISE EXCEPTION 'Insufficient school authority' USING ERRCODE='42501'; END IF;
  IF v_actor_role = 'school_admin' AND v_target_role = 'school_admin' THEN
    RAISE EXCEPTION 'School administrators cannot change another administrator'
      USING ERRCODE = '42501';
  END IF;

  SELECT id INTO v_actor_profile FROM public.profiles WHERE user_id = v_actor;
  IF v_actor_profile IS NULL THEN RAISE EXCEPTION 'Actor profile required for audit'; END IF;

  UPDATE public.gradifi_school_memberships
  SET status = p_new_status,
      activated_at = CASE
        WHEN p_new_status = 'active' AND activated_at IS NULL THEN now()
        ELSE activated_at
      END
  WHERE id = p_membership_id;

  INSERT INTO public.audit_logs
    (actor_id, action, entity, entity_id, "before", "after", metadata)
  VALUES
    (v_actor_profile, 'school_membership.status_changed',
     'gradifi_school_memberships', p_membership_id::text,
     jsonb_build_object('member_role', v_target_role, 'status', v_old_status),
     jsonb_build_object('member_role', v_target_role, 'status', p_new_status),
     jsonb_build_object('school_id', v_school_id, 'target_user_id', v_target_user));
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_cbt_answer(p_attempt_id uuid, p_question_id uuid, p_selected_option_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_attempt public.cbt_attempts%rowtype;
  v_snapshot public.gradifi_exam_question_snapshots%rowtype;
  v_correct_option uuid;
  v_marks integer;
  v_remaining integer;
  v_correct boolean;
  v_current_score integer;
begin
  select a.* into v_attempt from public.cbt_attempts a
  where a.id = p_attempt_id and public.cbt_candidate_is_owner(a.candidate_id) for update;
  if not found then raise exception 'CBT attempt not found or unauthorized'; end if;
  if v_attempt.status <> 'in_progress' then
    return jsonb_build_object('success',false,'error','CBT attempt is not active','status',v_attempt.status);
  end if;
  if now() >= v_attempt.deadline_at then
    perform public.cbt_finalize_attempt(p_attempt_id);
    return jsonb_build_object('success',false,'error','CBT attempt deadline has expired','status','timeout');
  end if;
  select * into v_snapshot from public.gradifi_exam_question_snapshots s
  where s.exam_id = v_attempt.exam_id and s.question_payload->>'question_id' = p_question_id::text;
  if not found then raise exception 'Question is not part of this attempt paper'; end if;
  if not exists (
    select 1 from jsonb_array_elements(v_snapshot.question_payload->'options') o
    where o->>'id' = p_selected_option_id::text
  ) then raise exception 'Selected option does not belong to this snapshot question'; end if;
  v_correct_option := (v_snapshot.answer_key_payload->>'correct_option_id')::uuid;
  v_marks := (v_snapshot.answer_key_payload->>'marks')::integer;
  v_correct := p_selected_option_id = v_correct_option;
  insert into public.cbt_answers(attempt_id, question_id, selected_option_id, is_correct, marks_awarded, updated_at)
  values (p_attempt_id, p_question_id, p_selected_option_id, v_correct, case when v_correct then v_marks else 0 end, now())
  on conflict (attempt_id, question_id) do update
  set selected_option_id = excluded.selected_option_id, is_correct = excluded.is_correct,
      marks_awarded = excluded.marks_awarded, updated_at = now();
  select coalesce(sum(marks_awarded),0) into v_current_score from public.cbt_answers where attempt_id = p_attempt_id;
  update public.cbt_attempts set score = v_current_score where id = p_attempt_id;
  v_remaining := greatest(0, extract(epoch from (v_attempt.deadline_at-now()))::integer);
  return jsonb_build_object('success',true,'attempt_id',p_attempt_id,'candidate_id',v_attempt.candidate_id,
    'question_id',p_question_id,'saved',true,'time_remaining',v_remaining,'current_score',v_current_score);
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_cbt_exam(p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
begin
  if auth.uid() is null or not exists (
    select 1 from public.cbt_attempts a
    where a.id = p_attempt_id and public.cbt_candidate_is_owner(a.candidate_id)
  ) then raise exception 'CBT attempt not found or unauthorized'; end if;
  return public.cbt_finalize_attempt(p_attempt_id);
end;
$function$

